// Get data from previous nodes (they run in parallel via merge)
const allData = $input.all();

// Extract data - these come from the 3 HTTP calls
const ordersRaw = allData[0]?.json;
const usersRaw = allData[1]?.json;
const productsRaw = allData[2]?.json;

const orders = Array.isArray(ordersRaw) ? ordersRaw : [];
const users = Array.isArray(usersRaw) ? usersRaw : [];
const products = Array.isArray(productsRaw) ? productsRaw : [];

// Calculate week boundaries
const now = new Date();
const weekAgo = new Date(now - 7 * 24 * 60 * 60 * 1000);

// Filter this week's data
const weekOrders = orders.filter(o => new Date(o.created_at) >= weekAgo);
const weekUsers = users.filter(u => new Date(u.created_at) >= weekAgo);
const weekProducts = products.filter(p => new Date(p.created_at) >= weekAgo);

// Calculate stats
const totalRevenue = weekOrders.reduce((sum, o) => sum + (o.total_price || o.price || 0), 0);
const avgOrderValue = weekOrders.length ? (totalRevenue / weekOrders.length).toFixed(0) : 0;

// Top categories
const catCount = {};
weekOrders.forEach(o => { if(o.category) catCount[o.category] = (catCount[o.category]||0) + 1; });
const topCat = Object.entries(catCount).sort((a,b) => b[1]-a[1])[0];

const weekStr = `${weekAgo.toLocaleDateString('en-IN')} – ${now.toLocaleDateString('en-IN')}`;

const html = `
<div style="font-family:'Segoe UI',sans-serif;max-width:640px;margin:0 auto;background:#f5f5f5;padding:24px;border-radius:12px;">
  <div style="background:linear-gradient(135deg,#0a0a14,#1a102a);padding:28px;border-radius:10px;text-align:center;margin-bottom:24px;">
    <h1 style="color:#e8b86d;margin:0;font-size:1.5rem;">📊 Weekly Report</h1>
    <p style="color:rgba(255,255,255,0.7);margin:6px 0 0;font-size:0.9rem;">${weekStr}</p>
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:24px;">
    <div style="background:white;padding:20px;border-radius:10px;border-left:4px solid #c8923a;box-shadow:0 2px 8px rgba(0,0,0,0.06);">
      <div style="font-size:1.8rem;font-weight:800;color:#c8923a;">${weekOrders.length}</div>
      <div style="color:#666;font-size:0.85rem;margin-top:4px;">Orders This Week</div>
    </div>
    <div style="background:white;padding:20px;border-radius:10px;border-left:4px solid #10b981;box-shadow:0 2px 8px rgba(0,0,0,0.06);">
      <div style="font-size:1.8rem;font-weight:800;color:#10b981;">₹${totalRevenue.toLocaleString('en-IN')}</div>
      <div style="color:#666;font-size:0.85rem;margin-top:4px;">Total Revenue</div>
    </div>
    <div style="background:white;padding:20px;border-radius:10px;border-left:4px solid #6366f1;box-shadow:0 2px 8px rgba(0,0,0,0.06);">
      <div style="font-size:1.8rem;font-weight:800;color:#6366f1;">${weekUsers.length}</div>
      <div style="color:#666;font-size:0.85rem;margin-top:4px;">New Users</div>
    </div>
    <div style="background:white;padding:20px;border-radius:10px;border-left:4px solid #f59e0b;box-shadow:0 2px 8px rgba(0,0,0,0.06);">
      <div style="font-size:1.8rem;font-weight:800;color:#f59e0b;">${weekProducts.length}</div>
      <div style="color:#666;font-size:0.85rem;margin-top:4px;">New Listings</div>
    </div>
  </div>
  <div style="background:white;padding:20px;border-radius:10px;margin-bottom:16px;">
    <h3 style="margin:0 0 12px;color:#333;">📈 Summary</h3>
    <p style="margin:4px 0;color:#555;">• Average order value: <strong>₹${avgOrderValue}</strong></p>
    <p style="margin:4px 0;color:#555;">• Total active products: <strong>${products.length}</strong></p>
    <p style="margin:4px 0;color:#555;">• Total registered users: <strong>${users.length}</strong></p>
    ${topCat ? `<p style="margin:4px 0;color:#555;">• Top category this week: <strong>${topCat[0]}</strong> (${topCat[1]} orders)</p>` : ''}
  </div>
  <div style="text-align:center;">
    <a href="https://nirvana-mart.onrender.com/nirvanamart-admin-portal" style="display:inline-block;background:#c8923a;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:700;">Open Admin Dashboard →</a>
  </div>
  <p style="color:#aaa;font-size:0.78rem;text-align:center;margin-top:20px;">NIRVANA MART Weekly Automation Report</p>
</div>`;

return [{
  json: {
    html,
    subject: `📊 NIRVANA MART — Weekly Report (${weekStr})`,
    stats: {
      week: weekStr,
      orders: weekOrders.length,
      revenue: totalRevenue,
      newUsers: weekUsers.length,
      newListings: weekProducts.length,
      avgOrderValue,
      totalUsers: users.length,
      totalProducts: products.length
    }
  }
}];
